    function open(context={}){buildEditor();state.context=context||{};state.sourceTextarea=resolveQuestionTextarea(state.context);state.document=state.context.initialSpec?Diagram.normalizeSpec(state.context.initialSpec):createDocument();if(state.document.mode!=='human-anatomy')state.document=createDocument();state.selectedId=null;state.activeTool='select';state.interaction=null;state.labelStart=null;state.history=[];state.historyIndex=-1;pushHistory();syncDocumentControls();setTool('select',false);render();state.root.hidden=false;document.body.dataset.qmxAnatomyOverflow=document.body.style.overflow||'';document.body.style.overflow='hidden';setStatus(state.context.initialSpec?'Existing human anatomy diagram loaded.':'Choose a body, organ, vessel, smart label, flow arrow or preset.');}
